  "implementation": "def solve(case):
    capacity = case['capacity']
    trials = case['trials']
    memory = []
    for idx, trial in enumerate(trials):
        entry = {
            'signature': trial['signature'],
            'reflection': trial['reflection'],
            'success': trial['success'],
            'index': idx
        }
        memory.append(entry)
        # Deduplicate failure signatures
        failure_groups = {}
        to_remove = set()
        for i, e in enumerate(memory):
            if not e['success']:
                sig = e['signature']
                if sig in failure_groups:
                    prev_i = failure_groups[sig]
                    if i > prev_i:
                        to_remove.add(prev_i)
                        failure_groups[sig] = i
                    else:
                        to_remove.add(i)
                else:
                    failure_groups[sig] = i
        for i in sorted(to_remove, reverse=True):
            del memory[i]
        if len(memory) > capacity:
            memory.sort(key=lambda e: (0 if not e['success'] else 1, -e['index'], e['signature']))
            memory = memory[:capacity]
    memory.sort(key=lambda e: e['index'])
    return [{'signature': e['signature'], 'reflection': e['reflection']} for e in memory]"
